    private TextFieldElement nameFilter() {
        return new TextFieldElement(page.locator("vaadin-text-field"));
    }

    private MultiSelectComboBoxElement statusFilter() {
        return MultiSelectComboBoxElement.getByLabel(page, "Status");
    }

    private String summaryText() {
        return page.getByText(SUMMARY).first().textContent();
    }

    @Test
    void typingNarrowsTheListAndUpdatesTheAddressBar() {
        queryLog.clear();

        nameFilter().getInputLocator().click();
        page.keyboard().type("aaltonen", new Keyboard.TypeOptions().setDelay(40));

        page.waitForURL("**?name=aaltonen");
        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);

        System.out.println("URL after typing: " + page.url());
