@@ -0,0 +1,109 @@
+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: a free-text name filter and a set of
+ * statuses.
+ *
+ * <p>A customer has to satisfy both parts. The name filter is split on
+ * whitespace into terms, and <em>every</em> term must occur in the first name or
+ * in the last name; comparison ignores case and accents on both sides, so
+ * {@code makinen} and {@code MÄKINEN} both find {@code Mäkinen}. An empty name
+ * filter and an empty status set each match everything.
+ *
+ * <p>This is a domain value: {@link CustomerRepository} applies it when it pages
+ * and when it counts, which is what keeps the grid lazily loaded.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.trim();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                // An EnumSet keeps the statuses in declaration order, which is
+                // the order the URL writes them in.
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** Convenience for a name-only filter. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** Whether this filter lets every customer through. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name filter split into the terms that all have to match. */
+    public List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return WHITESPACE.splitAsStream(name)
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toList();
+    }
+
+    /**
+     * Returns this filter as a predicate, with the name terms folded once up
+     * front rather than once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    /** Whether one customer passes this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * The case- and accent-insensitive form used on both sides of every
+     * comparison: {@code Joséphine} and {@code JOSEPHINE} both fold to
+     * {@code josephine}.
+     */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
