+        return parameters.isEmpty() ? "" : "?" + String.join("&", parameters);
+    }
+
+    // --- Applying the filter ------------------------------------------------
+
+    /**
+     * Reloads the grid and the summary for the current filter.
+     *
+     * @param handOverCount whether the count fetched here should answer the
+     *                      grid's next count query, so that one filter change
+     *                      costs one count query and one page query
+     */
+    private void refresh(boolean handOverCount) {
+        int matching = customerService.count(filter);
+        summary.setText("Showing " + matching + " of " + totalCustomers);
+        preparedCount = handOverCount ? matching : null;
+        grid.getDataProvider().refreshAll();
     }

